using Notifications.Legacy;

namespace Notifications;

/// <summary>Sends SMS messages.</summary>
public sealed class SmsClient
{
    public bool SendSms(Message message)
    {
#pragma warning disable CS0612, CS0618 // No replacement API is evidenced by the supplied context.
        return SmsApiV1.Send(message.Recipient.Phone, message.Body);
#pragma warning restore CS0612, CS0618
    }
}
